      @decided_at = decided_at
      @decided_by_kind = decided_by_kind
      @id = id
      @outcome = outcome
      @policy = policy
      @reasons = reasons
      freeze
    end

    # Builds a Decision from the API's JSON.
    def self.from_hash(data)
      new(
        decided_at: data.fetch("decided_at"),
        decided_by_kind: data.fetch("decided_by_kind"),
        id: data.fetch("id"),
        outcome: data.fetch("outcome"),
        policy: Policy.from_hash(data.fetch("policy")),
        reasons: data.fetch("reasons")
      )
    end
  end

  # A document of a case: its kind and where it stands. No byte of the file, its artifact or anything read from it leaves.
  class Document < Model
    MEMBERS = %i[capture captured_at decision document_type id in_force party_id received_at requirement side status].freeze

    # @return [String ("document", "selfie")]
    attr_reader :capture

    # When the client said it was captured, or null.
    # @return [String, nil]
    attr_reader :captured_at

    # The reviewer's decision in force about the document, the newest one, or null while nobody decided. The reviewer's reason never leaves through the API.
    # @return [DocumentDecision, nil]
    attr_reader :decision

    # The type of a document capture, such as CNH or RG; null for a selfie.
    # @return [String, nil]
    attr_reader :document_type

    # The document row.
    # @return [String]
    attr_reader :id

    # False for a document a newer capture replaced or that could not be used.
    # @return [Boolean]
    attr_reader :in_force

    # The party who presented it.
    # @return [String]
    attr_reader :party_id

    # When the file was received.
    # @return [String]
    attr_reader :received_at

    # What the document answers of what the case's workflow requires.
    # @return [String ("identity_document", "selfie")]
    attr_reader :requirement

    # front, back or single for a document capture; null for a selfie.
    # @return [String, nil]
    attr_reader :side

    # received, processed once its checks ran, refused when it cannot be used, or superseded when a newer capture replaced it.
    # @return [String]
    attr_reader :status

    def initialize(capture:, captured_at:, decision:, document_type:, id:, in_force:, party_id:, received_at:, requirement:, side:, status:)
      @capture = capture
      @captured_at = captured_at
      @decision = decision
      @document_type = document_type
      @id = id
      @in_force = in_force
      @party_id = party_id
      @received_at = received_at
      @requirement = requirement
      @side = side
      @status = status
      freeze
    end

    # Builds a Document from the API's JSON.
    def self.from_hash(data)
      new(
        capture: data.fetch("capture"),
        captured_at: data["captured_at"],
        decision: data["decision"]&.then { |value| DocumentDecision.from_hash(value) },
        document_type: data["document_type"],
        id: data.fetch("id"),
        in_force: data.fetch("in_force"),
        party_id: data.fetch("party_id"),
        received_at: data.fetch("received_at"),
        requirement: data.fetch("requirement"),
        side: data["side"],
        status: data.fetch("status")
      )
    end
  end

