  # What was checked, what was found and what was decided on a case. Evidence is summarized by what was measured and its result, never by an engine's raw output.
  class Dossier < Model
    MEMBERS = %i[checks created_at current_state decisions documents external_reference findings id kind livemode parties relationships reviews status status_market updated_at workflow].freeze

    # @return [Array<Check>]
    attr_reader :checks

    # @return [String]
