    # @return [String]
    attr_reader :current_state

    # Every decision taken on the case, oldest first.
    # @return [Array<Decision>]
    attr_reader :decisions

    # The documents and selfies of the case with the reviewers' decision about each, oldest first, as GET /v1/cases/{id}/documents lists them.
    # @return [Array<Document>]
    attr_reader :documents

    # @return [String]
    attr_reader :external_reference

    # @return [Array<Finding>]
    attr_reader :findings

    # @return [String]
    attr_reader :id

    # @return [String ("KYC", "KYB", "AGE")]
    attr_reader :kind

    # False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
    # @return [Boolean]
    attr_reader :livemode

    # @return [Array<DossierParty>]
    attr_reader :parties

    # @return [Array<Relationship>]
    attr_reader :relationships

    # @return [Array<Review>]
    attr_reader :reviews

    # @return [String ("open", "processing", "awaiting_input", "in_review", "approved", "rejected", "cancelled", "expired")]
    attr_reader :status

    # The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision.
    # @return [String ("PROCESSING", "PENDING_OCR", "PENDING", "APPROVED", "REPROVED", "BLOCKED", "CANCELLED", "EXPIRED")]
    attr_reader :status_market

    # @return [String]
    attr_reader :updated_at

    # The workflow run and its steps, or null before the case starts.
    # @return [DossierWorkflow, nil]
    attr_reader :workflow

    def initialize(checks:, created_at:, current_state:, decisions:, documents:, external_reference:, findings:, id:, kind:, livemode:, parties:, relationships:, reviews:, status:, status_market:, updated_at:, workflow:)
      @checks = checks
      @created_at = created_at
      @current_state = current_state
      @decisions = decisions
      @documents = documents
      @external_reference = external_reference
      @findings = findings
      @id = id
      @kind = kind
      @livemode = livemode
      @parties = parties
      @relationships = relationships
      @reviews = reviews
      @status = status
      @status_market = status_market
      @updated_at = updated_at
      @workflow = workflow
      freeze
    end

    # Builds a Dossier from the API's JSON.
    def self.from_hash(data)
      new(
        checks: data.fetch("checks").map { |item| Check.from_hash(item) },
        created_at: data.fetch("created_at"),
        current_state: data.fetch("current_state"),
        decisions: data.fetch("decisions").map { |item| Decision.from_hash(item) },
        documents: data.fetch("documents").map { |item| Document.from_hash(item) },
        external_reference: data.fetch("external_reference"),
        findings: data.fetch("findings").map { |item| Finding.from_hash(item) },
        id: data.fetch("id"),
        kind: data.fetch("kind"),
        livemode: data.fetch("livemode"),
        parties: data.fetch("parties").map { |item| DossierParty.from_hash(item) },
        relationships: data.fetch("relationships").map { |item| Relationship.from_hash(item) },
        reviews: data.fetch("reviews").map { |item| Review.from_hash(item) },
        status: data.fetch("status"),
        status_market: data.fetch("status_market"),
        updated_at: data.fetch("updated_at"),
        workflow: data["workflow"]&.then { |value| DossierWorkflow.from_hash(value) }
      )
    end
  end

  # A party in the dossier. Without party.pii.view the identifier is masked and the names and dates are left out; meta.full_pii says which.
  class DossierParty < Model
    MEMBERS = %i[birth_date cnae cnpj cpf full_name id identity_id kind natureza_juridica nome_fantasia primary razao_social situacao social_name].freeze

    # The birth date of a PERSON, when known. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :birth_date

    # The main CNAE activity code of a BUSINESS. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :cnae

    # The CNPJ of a BUSINESS as text. In full (normalized, ^[0-9A-Z]{12}[0-9]{2}$) for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *, as ************95.
    # @return [String, nil]
    attr_reader :cnpj

    # The CPF of a PERSON as text. In full (11 digits) for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *, as *********25.
    # @return [String, nil]
    attr_reader :cpf

    # The civil name of a PERSON. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :full_name

    # The party's identifier.
    # @return [String]
    attr_reader :id

    # The resolved identity the party was matched to, or null before resolution.
    # @return [String, nil]
    attr_reader :identity_id

    # @return [String ("PERSON", "BUSINESS")]
    attr_reader :kind

    # The legal nature code of a BUSINESS. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :natureza_juridica

    # The trade name of a BUSINESS. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :nome_fantasia

    # Whether the party is the primary subject of the case.
    # @return [Boolean]
    attr_reader :primary

    # The registered name of a BUSINESS. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :razao_social

    # The registration status of a BUSINESS. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :situacao

    # The social name of a PERSON, empty when none. Present only for a key with party.pii.view.
    # @return [String, nil]
    attr_reader :social_name

    def initialize(birth_date: nil, cnae: nil, cnpj: nil, cpf: nil, full_name: nil, id:, identity_id:, kind:, natureza_juridica: nil, nome_fantasia: nil, primary:, razao_social: nil, situacao: nil, social_name: nil)
