  # PartyProfile is an object of KUAA's API.
  class PartyProfile < Model
    MEMBERS = %i[cases cnpj cpf id identity kind livemode monitoring name party_ids screenings tags].freeze

    # The cases it takes part in, newest first. Null for a key without case.list.
    # @return [Array<PartyProfileCase>, nil]
    attr_reader :cases

    # The CNPJ of a BUSINESS as text, which may be alphanumeric. In full for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *.
    # @return [String, nil]
    attr_reader :cnpj

    # The CPF of a PERSON as text. In full (11 digits) for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *.
    # @return [String, nil]
    attr_reader :cpf

    # The profile: the id of the first party row of this CPF or CNPJ in the organization. GET /v1/parties/{id} takes it, or any party id of the same person or company.
    # @return [String]
    attr_reader :id

    # What KUAA verified about the identifier across cases. Null when nothing was, or for a key without identity.view.
    # @return [Identity, nil]
    attr_reader :identity

    # @return [String ("PERSON", "BUSINESS")]
    attr_reader :kind

    # False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
    # @return [Boolean]
    attr_reader :livemode

    # @return [Monitoring]
    attr_reader :monitoring

    # The full name of a person or the razão social of a company, from its newest party row. Null without party.pii.view.
    # @return [String, nil]
    attr_reader :name

    # Every party row of this CPF or CNPJ in the organization, oldest first.
    # @return [Array<String>]
    attr_reader :party_ids

    # The latest screening of each list among its party rows. Null for a key without evidence.view.
    # @return [Array<Screening>, nil]
    attr_reader :screenings

    # The tags its party rows carry, without repeats. Null for a key without tag.list.
    # @return [Array<PartyProfileTag>, nil]
    attr_reader :tags

    def initialize(cases:, cnpj:, cpf:, id:, identity:, kind:, livemode:, monitoring:, name:, party_ids:, screenings:, tags:)
      @cases = cases
      @cnpj = cnpj
      @cpf = cpf
      @id = id
      @identity = identity
      @kind = kind
      @livemode = livemode
      @monitoring = monitoring
      @name = name
      @party_ids = party_ids
      @screenings = screenings
      @tags = tags
      freeze
    end

    # Builds a PartyProfile from the API's JSON.
    def self.from_hash(data)
      new(
        cases: data["cases"]&.then { |value| value.map { |item| PartyProfileCase.from_hash(item) } },
        cnpj: data["cnpj"],
        cpf: data["cpf"],
        id: data.fetch("id"),
        identity: data["identity"]&.then { |value| Identity.from_hash(value) },
        kind: data.fetch("kind"),
        livemode: data.fetch("livemode"),
        monitoring: Monitoring.from_hash(data.fetch("monitoring")),
        name: data["name"],
        party_ids: data.fetch("party_ids"),
        screenings: data["screenings"]&.then { |value| value.map { |item| Screening.from_hash(item) } },
        tags: data["tags"]&.then { |value| value.map { |item| PartyProfileTag.from_hash(item) } }
      )
    end
  end

