  # Webhook is an object of KUAA's API.
  class Webhook < Model
    MEMBERS = %i[active created_at disabled_at disabled_reason events id name url].freeze

    # Whether events are delivered. An endpoint turned off keeps its deliveries waiting until it is turned on.
    # @return [Boolean]
    attr_reader :active

    # @return [String]
    attr_reader :created_at

    # @return [String, nil]
    attr_reader :disabled_at

    # Why the endpoint was turned off: consecutive_failures when its deliveries kept giving up, or what the person who turned it off wrote.
    # @return [String, nil]
    attr_reader :disabled_reason

    # @return [Array<String ("case.created", "case.updated", "check.completed", "decision.recorded", "review.recorded", "capture_session.finished", "document.decided")>]
    attr_reader :events

    # The endpoint identifier.
    # @return [String]
    attr_reader :id

    # @return [String]
    attr_reader :name

    # The https:// address the deliveries go to.
    # @return [String]
    attr_reader :url

    def initialize(active:, created_at:, disabled_at:, disabled_reason:, events:, id:, name:, url:)
      @active = active
      @created_at = created_at
      @disabled_at = disabled_at
      @disabled_reason = disabled_reason
      @events = events
      @id = id
      @name = name
      @url = url
      freeze
    end

    # Builds a Webhook from the API's JSON.
    def self.from_hash(data)
      new(
        active: data.fetch("active"),
        created_at: data.fetch("created_at"),
        disabled_at: data["disabled_at"],
        disabled_reason: data["disabled_reason"],
        events: data.fetch("events"),
        id: data.fetch("id"),
        name: data.fetch("name"),
        url: data.fetch("url")
      )
    end
  end

  # WebhookCreated is an object of KUAA's API.
  class WebhookCreated < Model
    MEMBERS = %i[active created_at disabled_at disabled_reason events id name secret url].freeze

    # Whether events are delivered. An endpoint turned off keeps its deliveries waiting until it is turned on.
    # @return [Boolean]
    attr_reader :active

    # @return [String]
    attr_reader :created_at

    # @return [String, nil]
    attr_reader :disabled_at

    # Why the endpoint was turned off: consecutive_failures when its deliveries kept giving up, or what the person who turned it off wrote.
    # @return [String, nil]
    attr_reader :disabled_reason

    # @return [Array<String ("case.created", "case.updated", "check.completed", "decision.recorded", "review.recorded", "capture_session.finished", "document.decided")>]
    attr_reader :events

    # The endpoint identifier.
    # @return [String]
    attr_reader :id

    # @return [String]
    attr_reader :name

    # The signing secret, in clear, this once. It is stored sealed and never answered again; a request replayed with the same Idempotency-Key answers null here. Lost, it is replaced by rotating the endpoint in the backoffice.
    # @return [String, nil]
    attr_reader :secret

    # The https:// address the deliveries go to.
    # @return [String]
    attr_reader :url

    def initialize(active:, created_at:, disabled_at:, disabled_reason:, events:, id:, name:, secret:, url:)
      @active = active
      @created_at = created_at
      @disabled_at = disabled_at
      @disabled_reason = disabled_reason
      @events = events
      @id = id
      @name = name
      @secret = secret
      @url = url
      freeze
    end

    # Builds a WebhookCreated from the API's JSON.
    def self.from_hash(data)
      new(
        active: data.fetch("active"),
        created_at: data.fetch("created_at"),
        disabled_at: data["disabled_at"],
        disabled_reason: data["disabled_reason"],
        events: data.fetch("events"),
        id: data.fetch("id"),
        name: data.fetch("name"),
        secret: data["secret"],
        url: data.fetch("url")
      )
    end
  end

  # The body of a webhook delivery. It carries no personal data; read the case through the API.
  class WebhookEvent < Model
    MEMBERS = %i[data datacontenttype id source specversion subject time type].freeze

    # @return [WebhookEventData]
    attr_reader :data

    # @return [String ("application/json")]
    attr_reader :datacontenttype

    # The event id: the same on every delivery of the event and on every retry. Deduplicate on it.
    # @return [String]
    attr_reader :id

    # urn:kuaa:tenant: and the tenant the event happened in.
    # @return [String]
    attr_reader :source

    # @return [String ("1.0")]
    attr_reader :specversion

    # cases/ and the case id.
    # @return [String]
    attr_reader :subject

    # @return [String]
    attr_reader :time

    # @return [String ("case.created", "case.updated", "check.completed", "decision.recorded", "review.recorded", "capture_session.finished", "document.decided")]
    attr_reader :type

    def initialize(data:, datacontenttype:, id:, source:, specversion:, subject:, time:, type:)
      @data = data
      @datacontenttype = datacontenttype
      @id = id
      @source = source
      @specversion = specversion
      @subject = subject
      @time = time
      @type = type
      freeze
    end

    # Builds a WebhookEvent from the API's JSON.
    def self.from_hash(data)
      new(
        data: WebhookEventData.from_hash(data.fetch("data")),
        datacontenttype: data.fetch("datacontenttype"),
        id: data.fetch("id"),
        source: data.fetch("source"),
        specversion: data.fetch("specversion"),
        subject: data.fetch("subject"),
        time: data.fetch("time"),
        type: data.fetch("type")
      )
    end
  end

  # WebhookEventData is an object of KUAA's API.
  class WebhookEventData < Model
    MEMBERS = %i[capture_session_id case_id check_id decision decision_id document_decision_id document_id document_side document_type environment event_id finished_at livemode occurred_at parent_case_id requirement review_id status status_market tenant_id type].freeze

    # Present on capture_session.finished: the hosted capture session the person sent, as answered when its link was issued.
    # @return [String, nil]
    attr_reader :capture_session_id

    # @return [String]
    attr_reader :case_id

    # Present on check.completed.
    # @return [String, nil]
    attr_reader :check_id

    # Present on document.decided: what the reviewer decided about the document. It never decides the case; the reviewer's reason is not sent.
    # @return [String ("approved", "rejected", "rerequested"), nil]
    attr_reader :decision

    # Present on decision.recorded.
    # @return [String, nil]
    attr_reader :decision_id

    # Present on document.decided: the decision a reviewer recorded about one document.
    # @return [String, nil]
    attr_reader :document_decision_id

    # Present on document.decided: the document the decision is about, as GET /v1/cases/{id}/documents lists it.
    # @return [String, nil]
    attr_reader :document_id

    # Present on document.decided for a document capture: front, back or single. Absent for a selfie.
    # @return [String, nil]
    attr_reader :document_side

    # Present on document.decided for a document capture: its type, such as CNH or RG. Absent for a selfie.
    # @return [String, nil]
    attr_reader :document_type

    # The environment of the tenant the event happened in. A sandbox event is about synthetic data and engine doubles.
    # @return [String ("live", "sandbox")]
    attr_reader :environment

    # The event id, the same as the envelope's id.
    # @return [String]
    attr_reader :event_id

    # Present on capture_session.finished: when the person sent the capture.
    # @return [String, nil]
    attr_reader :finished_at

    # False for an event of the organization's sandbox, true in production.
    # @return [Boolean]
    attr_reader :livemode

    # @return [String]
    attr_reader :occurred_at

    # Present on case.created and case.updated of a child case: the case whose workflow opened it. Absent otherwise.
    # @return [String, nil]
    attr_reader :parent_case_id

    # Present on document.decided: what the document answers.
    # @return [String ("identity_document", "selfie"), nil]
    attr_reader :requirement

    # Present on review.recorded.
    # @return [String, nil]
    attr_reader :review_id

    # What the event left behind: the case's status for case.*, the check's for check.completed, the outcome for decision.recorded, the reviewer's action for review.recorded, finished for capture_session.finished and the reviewer's decision about the document (approved, rejected or rerequested) for document.decided.
    # @return [String]
    attr_reader :status

    # Present on case.created, case.updated and capture_session.finished: The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision.
    # @return [String ("PROCESSING", "PENDING_OCR", "PENDING", "APPROVED", "REPROVED", "BLOCKED", "CANCELLED", "EXPIRED"), nil]
    attr_reader :status_market

    # @return [String]
    attr_reader :tenant_id

    # @return [String ("case.created", "case.updated", "check.completed", "decision.recorded", "review.recorded", "capture_session.finished", "document.decided")]
    attr_reader :type

    def initialize(capture_session_id: nil, case_id:, check_id: nil, decision: nil, decision_id: nil, document_decision_id: nil, document_id: nil, document_side: nil, document_type: nil, environment:, event_id:, finished_at: nil, livemode:, occurred_at:, parent_case_id: nil, requirement: nil, review_id: nil, status:, status_market: nil, tenant_id:, type:)
      @capture_session_id = capture_session_id
      @case_id = case_id
      @check_id = check_id
      @decision = decision
      @decision_id = decision_id
      @document_decision_id = document_decision_id
      @document_id = document_id
      @document_side = document_side
      @document_type = document_type
      @environment = environment
      @event_id = event_id
      @finished_at = finished_at
      @livemode = livemode
      @occurred_at = occurred_at
      @parent_case_id = parent_case_id
      @requirement = requirement
      @review_id = review_id
      @status = status
      @status_market = status_market
      @tenant_id = tenant_id
      @type = type
      freeze
    end

    # Builds a WebhookEventData from the API's JSON.
    def self.from_hash(data)
      new(
        capture_session_id: data["capture_session_id"],
        case_id: data.fetch("case_id"),
        check_id: data["check_id"],
        decision: data["decision"],
        decision_id: data["decision_id"],
        document_decision_id: data["document_decision_id"],
        document_id: data["document_id"],
        document_side: data["document_side"],
        document_type: data["document_type"],
        environment: data.fetch("environment"),
        event_id: data.fetch("event_id"),
        finished_at: data["finished_at"],
        livemode: data.fetch("livemode"),
        occurred_at: data.fetch("occurred_at"),
        parent_case_id: data["parent_case_id"],
        requirement: data["requirement"],
        review_id: data["review_id"],
        status: data.fetch("status"),
        status_market: data["status_market"],
        tenant_id: data.fetch("tenant_id"),
        type: data.fetch("type")
      )
    end
  end

