  # Workflow is an object of KUAA's API.
  class Workflow < Model
    MEMBERS = %i[default default_for id key latest_version name versions].freeze

    # True when a case of some kind runs this workflow when it names none.
    # @return [Boolean]
    attr_reader :default

    # The case kinds that run this workflow by default.
    # @return [Array<String ("KYC", "KYB", "AGE")>]
    attr_reader :default_for

    # The workflow definition; POST /v1/cases takes it, or its key, as workflow_definition_id.
    # @return [String]
    attr_reader :id

    # The workflow's key, such as br.kyc.
    # @return [String]
    attr_reader :key

    # The version a case starting now is pinned to.
    # @return [WorkflowVersion]
    attr_reader :latest_version

    # @return [String]
    attr_reader :name

    # Every published version, newest first.
    # @return [Array<WorkflowVersion>]
    attr_reader :versions

    def initialize(default:, default_for:, id:, key:, latest_version:, name:, versions:)
      @default = default
      @default_for = default_for
      @id = id
      @key = key
      @latest_version = latest_version
      @name = name
      @versions = versions
      freeze
    end

    # Builds a Workflow from the API's JSON.
    def self.from_hash(data)
      new(
        default: data.fetch("default"),
        default_for: data.fetch("default_for"),
        id: data.fetch("id"),
        key: data.fetch("key"),
        latest_version: WorkflowVersion.from_hash(data.fetch("latest_version")),
        name: data.fetch("name"),
        versions: data.fetch("versions").map { |item| WorkflowVersion.from_hash(item) }
      )
    end
  end

  # WorkflowList is an object of KUAA's API.
  class WorkflowList < Model
    MEMBERS = %i[livemode workflows].freeze

    # False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
